{
 "genere": "prevedi",
 "titolo": "Cosa restituisce?",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted


func run() -> Color:
	var normal_color := Color(1.0, 1.0, 1.0, 1.0)
	var dim_color := Color(0.5, 0.5, 0.5, 1.0)
	return normal_color * dim_color
",
   "domanda": "Che colore restituisce `run()`?",
   "spiegazione": "Moltiplicare due colori significa moltiplicare tra loro i singoli canali RGB e Alpha. Moltiplicare per `Color(0.5, 0.5, 0.5, 1.0)` dimezza la luminosità dei canali RGB, restituendo `(0.5, 0.5, 0.5, 1.0)`."
  },
  {
   "codice": "extends RefCounted


func run() -> Vector2:
	var start_pos := Vector2(-200.0, 100.0)
	var target_pos := Vector2(100.0, 100.0)
	var progress := 0.5
	return start_pos.lerp(target_pos, progress)
",
   "domanda": "Quanto vale il vettore restituito da `run()`?",
   "spiegazione": "La funzione `lerp()` calcola il punto intermedio tra due vettori in base al peso (0.5 significa a metà strada). La coordinata X tra -200 e 100 è -50, mentre la Y rimane fissa a 100. Il risultato è `Vector2(-50.0, 100.0)`."
  },
  {
   "codice": "extends RefCounted


func run() -> float:
	var current_modulate := Color(1.0, 1.0, 1.0, 0.8)
	var target_alpha := 0.0
	current_modulate.a = target_alpha
	return current_modulate.a
",
   "domanda": "Quanto vale l'alfa (`a`) alla fine?",
   "spiegazione": "Il canale `a` (alpha) di un colore gestisce la trasparenza. Modificandolo direttamente con `current_modulate.a = target_alpha`, il valore viene impostato a `0.0`."
  },
  {
   "codice": "extends RefCounted


func run() -> bool:
	var is_speaking := false
	var is_dimmed := true
	return not is_speaking and is_dimmed
",
   "domanda": "Cosa restituisce `run()`?",
   "spiegazione": "`is_speaking` è `false`, quindi `not is_speaking` diventa `true`. Visto che anche `is_dimmed` è `true`, entrambe le condizioni dell'operatore `and` sono verificate, restituendo `true`."
  }
 ]
